// Firebase Cloud Messaging service worker — thin wrapper.
//
// The real worker is /sw.js (generated by tool/generate_sw.dart): it owns the
// "/" scope for app-shell caching AND handles FCM background messages. Two
// workers cannot share one scope — the last registration would replace the
// other — so this file just runs the same code: whichever file the browser
// ends up activating, caching + push behave identically.
importScripts("/sw.js");
